@namespace sv_a429c93f925b4fadbc2b34de6df196bd.Components.Pages.Chat

<div class="channel-list">
    <h3 class="channel-list-header">Channels</h3>
    @foreach (var channel in Channels)
    {
        <div class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
             @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name"># @channel.Name</div>
            <div class="channel-description">@TruncateDescription(channel.Description)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<sv_a429c93f925b4fadbc2b34de6df196bd.Services.Channel> Channels { get; set; } = [];

    [Parameter]
    public int ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }
}

@namespace sv_a429c93f925b4fadbc2b34de6df196bd.Components.Pages.Chat
@using sv_a429c93f925b4fadbc2b34de6df196bd.Services
@inject IChatService ChatService

<div class="message-area">
    <div class="message-area-header">
        <h2># @Channel.Name</h2>
        <p>@Channel.Description</p>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (_isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in _messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReaction="HandleReaction" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-textarea"
                  @bind="_newMessageContent"
                  @bind:event="oninput"
                  placeholder="Message #@Channel.Name"
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(_newMessageContent)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Channel Channel { get; set; } = default!;

    [Parameter]
    public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback OnMessagesChanged { get; set; }

    private List<Message> _messages = [];
    private string _newMessageContent = string.Empty;
    private bool _isLoadingMore;
    private bool _allMessagesLoaded;
    private ElementReference _messageListRef;
    private int _currentChannelId;
    private const int PageSize = 30;

    protected override async Task OnParametersSetAsync()
    {
        if (_currentChannelId != Channel.Id)
        {
            _currentChannelId = Channel.Id;
            _messages = [];
            _allMessagesLoaded = false;
            await LoadMessages();
        }
    }

    private async Task LoadMessages()
    {
        var messages = await ChatService.GetMessagesAsync(Channel.Id, 0, PageSize);
        _messages = messages;
        if (messages.Count < PageSize)
            _allMessagesLoaded = true;
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — load older messages when near top
        if (_isLoadingMore || _allMessagesLoaded) return;

        _isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(Channel.Id, _messages.Count, PageSize);
        if (olderMessages.Count < PageSize)
            _allMessagesLoaded = true;

        _messages.InsertRange(0, olderMessages);
        _isLoadingMore = false;
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(_newMessageContent)) return;

        var sent = await ChatService.SendMessageAsync(Channel.Id, _newMessageContent.Trim(), null);
        _messages.Add(sent);
        _newMessageContent = string.Empty;
        await OnMessagesChanged.InvokeAsync();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh to show updated reactions
        await LoadMessages();
    }

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.GetValueOrDefault(messageId, 0);
    }
}

@namespace sv_a429c93f925b4fadbc2b34de6df196bd.Components.Pages.Chat
@using sv_a429c93f925b4fadbc2b34de6df196bd.Services
@inject IChatService ChatService

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    <div class="thread-root-message">
        <div class="message-header">
            <span class="message-author">@RootMessage.Author</span>
            <span class="message-time">@FormatRelativeTime(RootMessage.SentAt)</span>
        </div>
        <div class="message-content">@RootMessage.Content</div>
    </div>

    <hr class="thread-divider" />

    <div class="thread-replies">
        @if (_replies is null)
        {
            <div class="loading-indicator">Loading replies...</div>
        }
        else
        {
            @foreach (var reply in _replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        }
    </div>

    <div class="thread-input-area">
        <textarea class="message-textarea"
                  @bind="_replyContent"
                  @bind:event="oninput"
                  placeholder="Reply..."
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(_replyContent)">
            Reply
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Message RootMessage { get; set; } = default!;

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback OnReplySent { get; set; }

    private List<Message>? _replies;
    private string _replyContent = string.Empty;
    private int _loadedThreadId;

    protected override async Task OnParametersSetAsync()
    {
        if (_loadedThreadId != RootMessage.Id)
        {
            _loadedThreadId = RootMessage.Id;
            _replies = null;
            await LoadThread();
        }
    }

    private async Task LoadThread()
    {
        _replies = await ChatService.GetThreadAsync(RootMessage.Id);
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(_replyContent)) return;

        var reply = await ChatService.SendMessageAsync(RootMessage.ChannelId, _replyContent.Trim(), RootMessage.Id);
        _replies ??= [];
        _replies.Add(reply);
        _replyContent = string.Empty;
        await OnReplySent.InvokeAsync();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendReply();
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

