@namespace sv_a429c93f925b4fadbc2b34de6df196bd.Components.Pages.Chat
@using sv_a429c93f925b4fadbc2b34de6df196bd.Services
@inject IChatService ChatService

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    <div class="thread-root-message">
        <div class="message-header">
            <span class="message-author">@RootMessage.Author</span>
            <span class="message-time">@FormatRelativeTime(RootMessage.SentAt)</span>
        </div>
        <div class="message-content">@RootMessage.Content</div>
    </div>

    <hr class="thread-divider" />

    <div class="thread-replies">
        @if (_replies is null)
        {
            <div class="loading-indicator">Loading replies...</div>
        }
        else
        {
            @foreach (var reply in _replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        }
    </div>

    <div class="thread-input-area">
        <textarea class="message-textarea"
                  @bind="_replyContent"
                  @bind:event="oninput"
                  placeholder="Reply..."
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(_replyContent)">
            Reply
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Message RootMessage { get; set; } = default!;

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback OnReplySent { get; set; }

    private List<Message>? _replies;
    private string _replyContent = string.Empty;
    private int _loadedThreadId;

    protected override async Task OnParametersSetAsync()
    {
        if (_loadedThreadId != RootMessage.Id)
        {
            _loadedThreadId = RootMessage.Id;
            _replies = null;
            await LoadThread();
        }
    }

    private async Task LoadThread()
    {
        _replies = await ChatService.GetThreadAsync(RootMessage.Id);
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(_replyContent)) return;

        var reply = await ChatService.SendMessageAsync(RootMessage.ChannelId, _replyContent.Trim(), RootMessage.Id);
        _replies ??= [];
        _replies.Add(reply);
        _replyContent = string.Empty;
        await OnReplySent.InvokeAsync();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendReply();
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

