@page "/chat"
@using sv_a429c93f925b4fadbc2b34de6df196bd.Services
@using sv_a429c93f925b4fadbc2b34de6df196bd.Components.Pages.Chat
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_activeThread is null ? "chat-main-full" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea Channel="_activeChannel"
                         ThreadReplyCounts="_threadReplyCounts"
                         OnOpenThread="OpenThread"
                         OnMessagesChanged="RefreshThreadCounts" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_activeThread is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_activeThread"
                         OnClose="CloseThread"
                         OnReplySent="HandleThreadReplySent" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _activeChannel;
    private int _activeChannelId;
    private Message? _activeThread;
    private Dictionary<int, int> _threadReplyCounts = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _activeThread = null;

        await ChatService.MarkChannelReadAsync(channelId);
        await RefreshThreadCounts();
    }

    private async Task OpenThread(int messageId)
    {
        var messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, 100);
        _activeThread = messages.FirstOrDefault(m => m.Id == messageId);
        if (_activeThread is null)
        {
            // The message might be in an older page; fetch the thread directly
            var threadMessages = await ChatService.GetThreadAsync(messageId);
            // Use a placeholder if we can't find the root
        }
    }

    private void CloseThread()
    {
        _activeThread = null;
    }

    private async Task HandleThreadReplySent()
    {
        await RefreshThreadCounts();
    }

    private async Task RefreshThreadCounts()
    {
        if (_activeChannel is null) return;

        var messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, 100);
        _threadReplyCounts = new Dictionary<int, int>();

        // Build reply counts from messages that have ReplyToId
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            _threadReplyCounts[rootId] = _threadReplyCounts.GetValueOrDefault(rootId, 0) + 1;
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    border-right: 1px solid #1e1f22;
    overflow-y: auto;
}

.channel-list-header {
    padding: 16px;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
